-- Storage keys (#216, #21 part 2, docs/engineering/storage.md). `workspace_key` holds one wrapped
-- data-encryption key per workspace (AES-256-GCM under the KEK named by kek_id, AAD = workspace
-- id). It is a tenant table: ENABLE + FORCE RLS and `ws_isolation` in this same migration. KEK
-- rotation (`rewrapAll`) must find every workspace whose key is still under an old KEK, so the
-- owner gets a narrow `owner_definer_read` policy backing the SECURITY DEFINER lookup
-- app_workspace_keys_for_rewrap(text), which returns workspace ids only, never key bytes.
-- Crypto-erase zeroes wrapped_dek and sets destroyed_at (workspace_key_destroyed_zeroed_chk).
CREATE TABLE "workspace_key" (
	"wrapped_dek" "bytea" NOT NULL,
	"kek_id" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"destroyed_at" timestamp with time zone,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "workspace_key_pkey" PRIMARY KEY("workspace_id"),
	CONSTRAINT "workspace_key_destroyed_zeroed_chk" CHECK ("workspace_key"."destroyed_at" is null or ltrim(encode("workspace_key"."wrapped_dek", 'hex'), '0') = '')
);
